for i in range(1, 10):
    for j in range(1, 10):
        print(f'{i}×{j}={i*j:2d}', end=' ')
    print()  # 换行

score = 85
if score >= 90:
    print('优秀')
elif score >= 80:
    print('良好')
elif score >= 60:
    print('及格')
else:
    print('不及格')

grade = 'B'
if grade == 'A':
    print('90-100分')
elif grade == 'B':
    print('80-89分')
else:
    print('其他')

num1 = 10
num2 = 5
op = '+'
if op == '+':
    result = num1 + num2
elif op == '-':
    result = num1 - num2
else:
    result = '不支持的运算'
print(f'{num1} {op} {num2} = {result}')
